import java.util.Arrays;
import java.util.Random;
import java.util.Scanner;

public class BubbleSort {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.println("Enter the size of the array: ");
        int size = scanner.nextInt();

        int[] array = new int[size];

        System.out.println("Choose an option: ");
        System.out.println("1. Manual input");
        System.out.println("2. Random generation");

        int option = scanner.nextInt();

        if (option == 1) {
            System.out.println("Enter the array elements: ");
            for (int i = 0; i < size; i++) {
                array[i] = scanner.nextInt();
            }
        } else if (option == 2) {
            System.out.println("Enter the range of random generation (start end): ");
            int start = scanner.nextInt();
            int end = scanner.nextInt();

            Random random = new Random();
            for (int i = 0; i < size; i++) {
                array[i] = random.nextInt(end - start + 1) + start;
            }
        } else {
            System.out.println("Invalid option");
            return;
        }

        System.out.println("Choose a sorting order: ");
        System.out.println("1. Ascending");
        System.out.println("2. Descending");

        int order = scanner.nextInt();

        if (order == 1) {
            bubbleSortAscending(array);
        } else if (order == 2) {
            bubbleSortDescending(array);
        } else {
            System.out.println("Invalid order");
            return;
        }

        System.out.println("Sorted array: " + Arrays.toString(array));
    }

    public static void bubbleSortAscending(int[] array) {
        int n = array.length;
        int comparisons = 0;
        int swaps = 0;

        for (int i = 0; i < n - 1; i++) {
            boolean swapped = false;

            for (int j = 0; j < n - i - 1; j++) {
                if (array[j] > array[j + 1]) {
                    swap(array, j, j + 1);
                    swapped = true;
                    swaps++;
                }
                comparisons++;
            }

            if (!swapped) {
                break;
            }

            System.out.println("Pass " + (i + 1) + ": " + Arrays.toString(array));
        }

        System.out.println("Comparisons: " + comparisons);
        System.out.println("Swaps: " + swaps);
    }

    public static void bubbleSortDescending(int[] array) {
        int n = array.length;
        int comparisons = 0;
        int swaps = 0;

        for (int i = 0; i < n - 1; i++) {
            boolean swapped = false;

            for (int j = 0; j < n - i - 1; j++) {
                if (array[j] < array[j + 1]) {
                    swap(array, j, j + 1);
                    swapped = true;
                    swaps++;
                }
                comparisons++;
            }

            if (!swapped) {
                break;
            }

            System.out.println("Pass " + (i + 1) + ": " + Arrays.toString(array));
        }

        System.out.println("Comparisons: " + comparisons);
        System.out.println("Swaps: " + swaps);
    }

    public static void swap(int[] array, int i, int j) {
        int temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

To implement a recursive function to calculate the factorial of a given number with a time complexity of O(1), you can use memoization to store previously computed values. Here's an example implementation:

```cpp
#include <iostream>
#include <unordered_map>

std::unordered_map<int, int> factorialCache;

int factorial(int n) {
    if (n < 0) {
        throw std::invalid_argument("Factorial not defined for negative numbers.");
    }

    if (n <= 1) {
        return 1;
    }

    if (factorialCache.find(n) != factorialCache.end()) {
        return factorialCache[n];
    }

    int result = n * factorial(n - 1);
    factorialCache[n] = result;
    return result;
}

int main() {
    int number;
    std::cout << "Enter a number: ";
    std::cin >> number;

    try {
        int result = factorial(number);
        std::cout << "Factorial of " << number << " is: " << result << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Error: " << e.what() << std::endl;
    }

    return 0;
}
```

In this implementation, we use a `std::unordered_map` called `factorialCache` to store previously computed factorials. Before calculating the factorial for any number, we check if it exists in the cache. If it does, we simply return the cached value instead of performing the recursion again. If it doesn't exist, we calculate the factorial recursively, store it in the cache, and return the result.

By using memoization, we avoid repetitive calculations and achieve a time complexity of O(1) for subsequent factorials that have already been computed.

