function createUser(name, age, location, hobbies) {
  // Validate the name parameter
  if (typeof name !== 'string' || name.length < 3 || /\d|\W/.test(name)) {
    throw new Error('Invalid name. Name must be a string containing at least 3 characters and cannot contain any special characters or numbers.');
  }

  // Validate the age parameter
