import java.util.Scanner;

public class FibonacciSum {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt the user to enter a prime number greater than 10
        int n;
        do {
            System.out.print("Enter a prime number greater than 10: ");
            n = scanner.nextInt();
        } while (!isPrime(n) || n <= 10);

        // Calculate the sum of the first n Fibonacci numbers
        long sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += fibonacci(i);
        }

        System.out.println("The sum of the first " + n + " Fibonacci numbers is: " + sum);

        scanner.close();
    }

    // Function to check if a number is prime
    public static boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(num); i++) {
            if (num % i == 0) {
                return false;
            }
        }

        return true;
    }

    // Function to calculate the Fibonacci number at a given position
    public static long fibonacci(int n) {
        if (n <= 1) {
            return n;
        }

        long fib = 1;
        long prevFib = 1;

        for (int i = 2; i < n; i++) {
            long temp = fib;
            fib += prevFib;
            prevFib = temp;
        }

        return fib;
    }
}
