        ArrayList<String> permutations = new ArrayList<>();
        backtrack(permutations, new StringBuilder(), input.toCharArray(), new boolean[input.length()]);
        return permutations;
    }

    private static void backtrack(ArrayList<String> permutations, StringBuilder current, char[] input, boolean[] used) {
        if (current.length() == input.length) {
            permutations.add(current.toString());
            return;
        }

        for (int i = 0; i < input.length; i++) {
            if (used[i]) {
                continue;
            }

            if (i > 0 && input[i] == input[i-1] && !used[i-1]) {
                continue;
            }

            used[i] = true;
            current.append(input[i]);
            backtrack(permutations, current, input, used);
            current.deleteCharAt(current.length() - 1);
            used[i] = false;
        }
    }

    public static void main(String[] args) {
        String input = "aab";
        ArrayList<String> permutations = getPermutations(input);
        for (String permutation : permutations) {
