Here's a JavaScript program that prints all the prime numbers from 0 to a given number `n` with a time complexity of `O(n*log(log(n)))`:

```javascript
function printPrimeNumbers(n) {
  // Create a boolean array "isPrime[0..n]" and initialize all entries it as true
  let isPrime = new Array(n + 1).fill(true);

  for (let p = 2; p * p <= n; p++) {
    // If isPrime[p] is not changed, then it is a prime
    if (isPrime[p]) {
      // Update all multiples of p
      for (let i = p * p; i <= n; i += p) {
        isPrime[i] = false;
      }
    }
  }

  // Print all prime numbers
  for (let p = 2; p <= n; p++) {
    if (isPrime[p]) {
      console.log(p);
    }
  }
}

// Test the function
printPrimeNumbers(100);
```

