// LibraryItem class
class LibraryItem {
  private String title;
  private String author;
  private int yearPublished;

  public LibraryItem(String title, String author, int yearPublished) {
    this.title = title;
    this.author = author;
    this.yearPublished = yearPublished;
  }

  public String getTitle() {
    return title;
  }

  public String getAuthor() {
    return author;
  }

  public int getYearPublished() {
    return yearPublished;
  }

  @Override
  public String toString() {
    return "Title: " + title + "\nAuthor: " + author + "\nYear Published: " + yearPublished;
  }
}

// Book class
class Book extends LibraryItem implements Lendable {
  private String genre;
  private boolean isBorrowed;

  public Book(String title, String author, int yearPublished, String genre) {
    super(title, author, yearPublished);
    this.genre = genre;
    this.isBorrowed = false;
  }

  public String getGenre() {
    return genre;
  }

  @Override
  public boolean isAvailable() {
    return !isBorrowed;
  }

  @Override
  public void lend() {
    if (isAvailable()) {
      isBorrowed = true;
      System.out.println("Book has been borrowed.");
    } else {
      System.out.println("Book is already borrowed.");
    }
  }

  @Override
  public void returnItem() {
    if (isAvailable()) {
      System.out.println("Book is not borrowed.");
    } else {
      isBorrowed = false;
      System.out.println("Book has been returned.");
    }
  }

  @Override
  public String toString() {
    return super.toString() + "\nGenre: " + genre + "\nAvailability: " + (isAvailable() ? "Available" : "Borrowed");
  }
}

// Magazine class
class Magazine extends LibraryItem {
  private int issueNumber;

  public Magazine(String title, String author, int yearPublished, int issueNumber) {
    super(title, author, yearPublished);
    this.issueNumber = issueNumber;
  }

  public int getIssueNumber() {
    return issueNumber;
  }

  @Override
  public String toString() {
    return super.toString() + "\nIssue Number: " + issueNumber;
  }
}

// Lendable interface
interface Lendable {
  boolean isAvailable();
  void lend();
  void returnItem();
}

// LibrarySystem class
public class LibrarySystem {
  public static void main(String[] args) {
    // Create instances of books
    Book book1 = new Book("Harry Potter and the Philosopher's Stone", "J.K. Rowling", 1997, "Fantasy");
    Book book2 = new Book("To Kill a Mockingbird", "Harper Lee", 1960, "Classic");
    Book book3 = new Book("The Great Gatsby", "F. Scott Fitzgerald", 1925, "Classic");

    // Create instances of magazines
    Magazine magazine1 = new Magazine("National Geographic", "Various Authors", 1888, 100);
    Magazine magazine2 = new Magazine("Time", "Various Authors", 1923, 900);

    // Display book and magazine details
    System.out.println("Books:");
    System.out.println(book1);
    System.out.println("\n" + book2);
    System.out.println("\n" + book3);

    System.out.println("\nMagazines:");
    System.out.println(magazine1);
    System.out.println("\n" + magazine2);

    // Lend and return books
    System.out.println("\nLending and returning books:");
    book1.lend(); // Borrow the book
    book1.lend(); // Attempt to borrow the book again
    book1.returnItem(); // Return the book

    // Check book availability
    System.out.println("\nBook availability:");
    System.out.println(book1.getTitle() + " - " + (book1.isAvailable() ? "Available" : "Borrowed"));
  }
}
