# Global variable to keep track of generated numbers
generated_numbers = []

def generate_random_number(lower_limit, upper_limit):
    while True:
        # Generate a random number within the range
        random_number = random.randint(lower_limit, upper_limit)

        # Check if the number satisfies the conditions
        if (random_number % 3 == 0 and
            random_number % 4 != 0 and
            is_prime(random_number) and
            is_fibonacci(random_number)):
            # Check if the number has already been generated
            if random_number not in generated_numbers:
                # Add the number to the generated_numbers list
                generated_numbers.append(random_number)
                return random_number

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_fibonacci(n):
    if n == 0 or n == 1:
        return True
    return is_fibonacci_helper(n, 0, 1)

def is_fibonacci_helper(n, a, b):
    c = a + b
    if c == n:
        return True
    if c > n:
        return False
    return is_fibonacci_helper(n, b, c)

